In this Java class representing Sprint progress, what will be printed?

class Sprint {
    String name;
    int totalStoryPoints;
    int completedPoints;

    Sprint(String name, int total) {
        this.name = name;
        this.totalStoryPoints = total;
        this.completedPoints = 0;
    }

    void completeStory(int points) {
        if(completedPoints + points <= totalStoryPoints) {
            completedPoints += points;
        }
    }

    double getCompletionPercentage() {
        return (double)completedPoints / totalStoryPoints * 100;
    }
}

public class Main {
    public static void main(String[] args) {
        Sprint sprint = new Sprint("Sprint 1", 20);
        sprint.completeStory(8);
        sprint.completeStory(5);
        sprint.completeStory(10);
        System.out.println((int)sprint.getCompletionPercentage());
    }
}

